import json

class GSLMatrix(ctypes.Structure):
    _fields_ = [('nrows', ctypes.c_int), ('ncols', ctypes.c_int), ('data', ctypes.POINTER(ctypes.c_double))]

def is_positive_definite(matrix):
    m = GSLMatrix()
    m.nrows = len(matrix)
    m.ncols = len(matrix[0])
    m.data = (ctypes.c_double * (m.nrows * m.ncols))(*[float(x) for row in matrix for x in row])
    return gsl.gsl_linalg_cholesky_is_pd(m)

def cholesky_decomp(matrix):
    if not is_positive_definite(matrix):
        raise ValueError("Matrix is not positive definite.")

    m = GSLMatrix()
    m.nrows = len(matrix)
    m.ncols = len(matrix[0])
    m.data = (ctypes.c_double * (m.nrows * m.ncols))(*[float(x) for row in matrix for x in row])
    L = gsl.gsl_linalg_cholesky_decomp(m)
    return [[L.data[i + j * L.nrows] for j in range(i + 1)] for i in range(L.nrows)]

